#Popup {
    flow: vertical;
    padding: 4 0;
    auto-size: grow fit;
    gap: 8;

    & > #ItemList {
        auto-size: grow fit;
        flow: vertical;
        gap: 2;
    }

    & > #EmptyPlaceholder {
        auto-size: grow fit;
        is-visible: false;
        font: 0;
        font-size: 11;
        color: "Widget.PopupMenuTextMuted";
        outline-color: "Widget.PopupMenuTextOutline";
        outline-size: 1;
        padding: 6 8;
        text-align: middle-center;
        word-wrap: true;
        text-overflow: false;
        border-color: "Widget.PopupBorder";
        border-width: 1 0 0 0;
    }
}

.separator {
    auto-size: grow fit;
    size: 0 11;
    margin: 0 4;
    background-color: 0;

    & > .separator-line {
        anchor: middle-center;
        auto-size: grow fit;
        size: 0 1;
        background-color: "Widget.PopupBorder";
    }
}

.item {
    auto-size: grow fit;
    gap: 8;
    size: 0 36;
    margin: 0 4;
    transition-type: ease-out-sine;
    transition-duration: 250;
    background-color: 0;

    &:hover {
        background-color: "Widget.PopupMenuBackgroundHover";
        transition-duration: 50;
    }

    & > .icon-wrapper {
        anchor: middle-left;
        size: 36;

        & > .icon {
            anchor: middle-center;
            text-align: middle-center;

            &.fa-icon {
                font: 2;
                font-size: 16;
                color: "Widget.PopupMenuText";
                outline-color: "Widget.PopupMenuTextOutline";
                outline-size: 1;
                text-offset: 0 1;
            }

            &.game-icon {
                size: 30 30;
                border-radius: 3;
            }

            &.glyph-icon {
                font: 0;
                font-size: 16;
                color: "Widget.PopupMenuText";
                outline-color: "Widget.PopupMenuTextOutline";
                outline-size: 1;
            }

            &.fa-icon.disabled {
                color: "Widget.PopupMenuTextDisabled";
                outline-color: 0;
            }

            &.glyph-icon.disabled {
                color: "Widget.PopupMenuTextDisabled";
                outline-color: 0;
            }

            &.disabled { image-grayscale: true; }
        }
    }

    & > .text {
        auto-size: grow fit;
        anchor: middle-left;
        font-size: 13;
        color: "Widget.PopupMenuText";
        outline-color: "Widget.PopupMenuTextOutline";
        outline-size: 1;
        padding: 0 8 0 0;

        &:hover {
            color: "Widget.PopupMenuTextHover";
            outline-color: "Widget.PopupMenuTextOutlineHover";
        }

        &.disabled { color: "Widget.PopupMenuTextDisabled"; outline-color: 0; }
    }

    & > .text-alt {
        anchor: middle-left;
        font-size: 11;
        color: "Widget.PopupMenuTextMuted";
        outline-color: "Widget.PopupMenuTextOutline";
        outline-size: 1;
        padding: 0 8 0 0;

        &.disabled { color: "Widget.PopupMenuTextDisabled"; outline-color: 0; }
    }
}
